  await TestValidator.error(
    "delete already deleted session should fail",
    async () => {
      await api.functional.todoList.user.todoListUsers.todoListUserSessions.erase(
        connection,
        {
          userId: user1.id,
          sessionId: session.sessionId,
        },
      );
    },
  );
